#!/usr/bin/env bun
// Generate src/bun/recommended-rules.js from tests/conformance/eslint/lib/rules/.
//
// Scans the ESLint core rules directory, filters out deprecated rules, and
// emits one static `require(...)` per rule.  These static requires are what
// `bun build --compile` follows when bundling the standalone binary, so the
// shape of this generated file directly determines which rules a user can
// reference in their eslint.config.js.
//
// Run: `bun tools/gen-bundled-rules.js`
//
// The output replaces the entire src/bun/recommended-rules.js — re-run
// whenever an ESLint upgrade adds/removes core rules.

"use strict";

const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.resolve(__dirname, "..");
const RULES_DIR = path.join(ROOT, "tests/conformance/eslint/lib/rules");
const OUT = path.join(ROOT, "src/bun/recommended-rules.js");

function isRule(file) {
  return file.endsWith(".js") && file !== "index.js";
}

function readDeprecated(file) {
  // Look for `deprecated: true` (or `deprecated: { ... }`) in meta.
  // ESLint v9+ uses `meta.deprecated` as either a boolean or an object.
  const src = fs.readFileSync(path.join(RULES_DIR, file), "utf8");
  // Cheap regex-based check; the false positives are negligible because
  // we only run this at generation time, not per-file at runtime.
  return /^\s*deprecated\s*:\s*(true|\{)/m.test(src);
}

function gen() {
  const files = fs.readdirSync(RULES_DIR).filter(isRule).sort();
  const rules = files
    .map(f => ({ name: f.slice(0, -3), file: f, deprecated: readDeprecated(f) }))
    .filter(r => !r.deprecated);

  const head = [
    "// GENERATED by tools/gen-bundled-rules.js — do not edit by hand.",
    "// Re-run after ESLint upgrades that add/remove core rules.",
    "//",
    "// Each `require(...)` below is a static import the bundler can follow.",
    "// `bun build --compile` walks this graph and inlines every rule module",
    "// (plus its transitive dependencies — eslint-visitor-keys, esquery, etc.)",
    "// into the standalone ezlint binary.  Without this static enumeration,",
    "// rule modules would only be reachable through dynamic require paths",
    "// (api.js's loadCoreRules / rules.bundle.js), which the bundler can't",
    "// follow into the compiled binary.",
    "//",
    "// All non-deprecated core rules are included.  Deprecated rules are",
    "// filtered out at generation time (see tools/gen-bundled-rules.js).",
    "",
    `\"use strict\";`,
    "",
    "const RULE_MODULES = {",
  ];

  const body = rules.map(r =>
    `  ${JSON.stringify(r.name)}: require(${JSON.stringify("../../tests/conformance/eslint/lib/rules/" + r.file)}),`
  );

  const tail = [
    "};",
    "",
    "// Convert each module into the {meta, create} descriptor shape api.js wants.",
    "function _toDescriptor(name, ruleModule) {",
    "  if (!ruleModule || typeof ruleModule !== \"object\") return null;",
    "  const create = typeof ruleModule.create === \"function\" ? ruleModule.create : ruleModule;",
    "  if (typeof create !== \"function\") return null;",
    "  const meta = ruleModule.meta || {};",
    "  return {",
    "    meta: {",
    "      name,",
    "      defaultOptions: meta.defaultOptions,",
    "      schema: meta.schema,",
    "      messages: meta.messages,",
    "      fixable: meta.fixable,",
    "      deprecated: meta.deprecated,",
    "    },",
    "    create,",
    "  };",
    "}",
    "",
    "const DESCRIPTORS = Object.entries(RULE_MODULES)",
    "  .map(([name, mod]) => _toDescriptor(name, mod))",
    "  .filter(Boolean);",
    "",
    "module.exports = { DESCRIPTORS, RULE_NAMES: Object.keys(RULE_MODULES) };",
    "",
  ];

  const out = [...head, ...body, ...tail].join("\n");
  fs.writeFileSync(OUT, out);
  console.log(`wrote ${OUT}`);
  console.log(`  bundled ${rules.length} rules (${files.length - rules.length} deprecated, skipped)`);
}

if (require.main === module) gen();
